/* STARNW ($7F9A, bank 1) - New star at math RAM X: random visual X,Y,Z (RND8), Y and Z signs opposite of current M_YPH, M_ZPH;
 *   MS_S1UN (BIC low = ST_BIC) converts to universe coordinates, stored at 0,2,4(X)
 * Condition codes out: C.
 */
void starnw(void)
{
    CK(0x7F9A);
    CYC(8);
    JSR(rnd8);                                       /* L7F9A  SET UP VISUAL X,Y,Z */
    A = M8(RND_S1);                                  /* L7F9D */
    A &= 0x1F;                                       /* L7F9F */
    B = M8(RND_S2);                                  /* L7FA1 */
    wr16(X, D);                                      /* L7FA3 */
    D = (uint16_t)(A * B);                           /* L7FA5 */
    /* TST M_YPH */                                  /* L7FA6  B SELECT SIGN OPPOSITE OF CURRENT */
    CYC(36);
    if ((M8(M_YPH) & 0x80)) goto l_starnw_20;        /* L7FA9 */
    A = (uint8_t)(0 - A);                            /* L7FAB */
    CYC(2);
l_starnw_20:;
    CK(0x7FAC);
    wr16((uint16_t)(X + 2), D);                      /* L7FAC */
    A = M8(RND_S1);                                  /* L7FAE */
    A &= 0x1F;                                       /* L7FB0 */
    B = M8(RND_S3);                                  /* L7FB2 */
    mul_ab();                                        /* L7FB4 */
    CYC(37);
    if ((M8(M_ZPH) & 0x80)) goto l_starnw_30;        /* L7FB8 */
    A = neg8(A);                                     /* L7FBA */
    CYC(2);
l_starnw_30:;
    CK(0x7FBB);
    wr16((uint16_t)(X + 4), D);                      /* L7FBB */
    A = M8(ST_BIC);                                  /* L7FBD  REDO CURRENT STAR */
    CYC(10);
    hw_wr8(M_BICL, A);                               /* L7FBF */
    A = MS_S1UN;                                     /* L7FC2  DO POST ADD */
    CYC(15);
    JSR(mgowt);                                      /* L7FC4 */
    D = rd16(M_XP);                                  /* L7FC7  STORE UNIVERSE COORDINATES */
    wr16(X, D);                                      /* L7FCA */
    D = rd16(M_YP);                                  /* L7FCC */
    wr16((uint16_t)(X + 2), D);                      /* L7FCF */
    D = rd16(M_ZP);                                  /* L7FD1 */
    A &= 0xFF;                                       /* L7FD4 */
    B &= 0xFF;                                       /* L7FD6 */
    wr16((uint16_t)(X + 4), D);                      /* L7FD8 */
    /* RESTORE MATH BOX */
    /* BIC ALREADY UPDATED BY PREVIOUS OP */
    CYC(44);
    RTS;                                             /* L7FDA */
}

